```csharp
private void SendDesktopAlert(string message, string caption, Image? image = null)
{
    // If we’re not on the UI thread, re-invoke ourselves there
    if (InvokeRequired)
    {
        BeginInvoke((Action)(() => SendDesktopAlert(message, caption, image)));
        return;
    }

    if (image != null)
