                        return; // Success, exit early

                    }



                    SendDesktopAlert("Alert", $"Attempting to connect to API - Try #{i} ({result.Message ?? "No error detail"})");

                }

                catch (Exception ex)

                {

                    SendDesktopAlert("Alert", $"Attempt #{i} failed: {ex.Message}");

                }



